ROOT=Path(__file__).resolve().parent
NOW='2026-11-12'
def jwrite(name,obj): (ROOT/name).write_text(json.dumps(obj,ensure_ascii=False,indent=2,allow_nan=False)+'\n')
def csvwrite(name,rows):
 if not rows:raise ValueError(name)
 fields=list(dict.fromkeys(k for r in rows for k in r))
 with (ROOT/name).open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)
def sha(b):return hashlib.sha256(b).hexdigest()
def canonical(o):return json.dumps(o,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()
