 b=subprocess.check_output(['git','show',pins['pins'][label]+':'+path]);rr=[]
 for n,r in enumerate(csv.DictReader(io.StringIO(b.decode())),2):
  if r.get('iata') in codes:rr.append({'source_csv_record':n,'record_id':label+':'+path+':'+str(n),'row_sha256':sha(canonical(r)),'row':r})
