 b=subprocess.check_output(['git','show',pins['pins'][key]+':'+path]);rr=cityrows.get(key+':'+path,[]);ids={x['record_id'] for x in rr}
 for n,r in enumerate(csv.DictReader(io.StringIO(b.decode())),2):
  rid=key+':'+path+':'+str(n)
  if (r.get('iata') in want or r.get('source_id') in want) and rid not in ids:rr.append({'source_csv_record':n,'record_id':rid,'row_sha256':sha(canonical(r)),'row':r})
 cityrows[key+':'+path]=rr
