# Public schedule rows are offers at a station, never physical inventories.
class Tables(HTMLParser):
 def __init__(self):super().__init__();self.table=0;self.tr=None;self.td=None;self.rows=[]
 def handle_starttag(self,t,a):
  if t=='table':self.table+=1
  elif t=='tr':self.tr=[]
  elif t in ['td','th'] and self.tr is not None:self.td=[]
 def handle_data(self,d):
  if self.td is not None:self.td.append(d)
 def handle_endtag(self,t):
  if t in ['td','th'] and self.td is not None:self.tr.append(' '.join(' '.join(self.td).split()));self.td=None
  elif t=='tr' and self.tr is not None:self.rows.append((self.table,self.tr));self.tr=None
