  sch.append(dict(observation_id=f'{sid}:tr{i}',source_id=sid,source_row_id=f'table{table}:tr{i}',row_sha256=sha(canonical(cells)),source_sha256=rec[sid]['sha256'],airport_pair='IKT:'+code,direction='INTO_IKT' if table==1 else 'OUT_OF_IKT',carrier=cells[0],flight=cells[1],time_at_IKT=cells[2],weekdays_text=cells[3],period=cells[4],as_of=NOW,unit='опубликованная строка station schedule',grain='перевозчик/рейс/время/дни/начало',coverage='Только airport station page; valid_to не опубликован/не извлечён; одноимённые строки не складывать',status='PUBLISHED_STATION_OFFER',aircraft='UNKNOWN',nominal_seats='UNKNOWN',physical_inventory_id='UNKNOWN',open_seats='UNKNOWN',fare_rub='UNKNOWN',baggage='UNKNOWN',booking_lead_days='NOT_A_FARE_QUOTE',throughstop_status='UNKNOWN',sellable_protected_connection='UNKNOWN'))
