for startdate,season in [(datetime.date(2028,1,17),'winter_nonpeak'),(datetime.date(2028,7,10),'summer_trial3'),(datetime.date(2028,10,9),'shoulder')]:
 peak=season=='summer_trial3';days=[0,2,5] if peak else [0,3]
 for pid in ['P-IKT-RADIAL','P-IKT-BANK','P-IKT-ENDPOINT']:
  fs=[]
  if pid=='P-IKT-RADIAL':
   for d in days:
    for tail,spoke,offset in [('T1','NOZ',0),('T2','VVO',0),('T1','TOF',1),('T2','OMS',1)]:fs+=flychain(pid,startdate+datetime.timedelta(days=d+offset),tail,['IKT',spoke,'IKT'],8*60)
  elif pid=='P-IKT-ENDPOINT':
   for d in days:
    for tail,spoke,offset in [('T1','NOZ',0),('T2','TOF',0),('T1','IKT',1),('T2','OMS',1)]:fs+=flychain(pid,startdate+datetime.timedelta(days=d+offset),tail,['SVX',spoke,'SVX'],8*60)
  else:
   for ix,d in enumerate(days):
    # Each aircraft returns from the first spoke, waits through the 90-minute bank,
    # and operates the second roundtrip. No invented overnight shared tail.
    west_early=(ix%2==0)
    for tail,west,east in [('T1','NOZ','VVO'),('T2','TOF','OMS')]:
     first,second=(west,east) if west_early else (east,west)
     chain=flychain(pid,startdate+datetime.timedelta(days=d),tail,['IKT',first,'IKT'],6*60 if west_early else 4*60)
     # common second wave begins 90min after the later first-wave return
     arrivals=[2*duration('IKT',s)+45+(6*60 if west_early else 4*60) for s in (['NOZ','TOF'] if west_early else ['VVO','OMS'])]
     second_start=max(arrivals)+90
     more=flychain(pid,startdate+datetime.timedelta(days=d),tail,['IKT',second,'IKT'],second_start)
     for q in more:q['flight_instance_id']=q['flight_instance_id'].replace(':1',':3') if q['flight_instance_id'].endswith(':1') else q['flight_instance_id'][:-1]+'4'
     fs+=chain+more
  fragments+=fs
