# Add typographic boundaries to research prose only; pinned/source records remain exact.
def readable(v):
 if isinstance(v,dict):return {k:readable(x) for k,x in v.items()}
 if isinstance(v,list):return [readable(x) for x in v]
 if isinstance(v,str) and re.search('[А-Яа-яЁё]',v):
  v=re.sub(r'([А-Яа-яЁё])([0-9A-Za-z])',r'\1 \2',v)
  v=re.sub(r'([0-9A-Za-z])([А-Яа-яЁё])',r'\1 \2',v)
  v=re.sub(r'([,;])(?=[А-Яа-яЁёA-Za-z])',r'\1 ',v)
  for a_,b_ in {'недоговорныйспрос':'не договорный спрос','рабочиххвостов':'рабочих хвостов','неодинаковый':'не одинаковый','свободныйфлот':'свободный флот','существенный':'существенный','местнаябаза':'местная база','техническоеприсутствие':'техническое присутствие','сохранитьпроисхождение':'сохранить происхождение','региональныхлиний':'региональных линий','вакансияэкипажа':'вакансия экипажа','пассажирообслуживаний':'пассажирообслуживаний','своирейсы':'свои рейсы','условныйрезерв':'условный резерв','прямогокандидата':'прямого кандидата','неподтверждённыйспрос':'неподтверждённый спрос','договорныйспрос':'договорный спрос','новыепродукты':'новые продукты','прямогорейса':'прямого рейса','собственныепродажи':'собственные продажи','нетприбыли':'нет прибыли','нетдоговора':'нет договора','обестороны':'обе стороны','недостаточны':'недостаточны'}.items():v=v.replace(a_,b_)
 return v
